insert into public.initiatives(id,title,description,specification) values('core-platform','TDA Developer Portal & Core Monorepo','The primary centralized production platform housing Member Profiles, Projects, Problem Bank, Announcements, and Admin Management in one unified Next.js + PostgreSQL codebase.','{"id":"core-platform","title":"TDA Developer Portal & Core Monorepo","track":"core","stage":"MVP Phase 1","description":"The primary centralized production platform housing Member Profiles, Projects, Problem Bank, Announcements, and Admin Management in one unified Next.js + PostgreSQL codebase.","stack":["Next.js 15 App Router","TypeScript","PostgreSQL","Prisma ORM","Auth.js v5","Tailwind CSS","shadcn/ui","Zod"],"guidelines":["Do not split frontend and backend into separate microservices or isolated repos.","Strictly follow the official Next.js App Router Dashboard course architecture.","Enforce server-side Zod validation on all Server Actions and route handlers.","Role-Based Access Control (RBAC): Public, Member, Contributor, Mentor, Project Lead, Admin."],"resources":[{"name":"Official Next.js Dashboard Course","url":"https://nextjs.org/learn"},{"name":"Auth.js v5 Documentation","url":"https://authjs.dev"},{"name":"Prisma PostgreSQL Quickstart","url":"https://www.prisma.io/docs/getting-started"},{"name":"shadcn/ui Component Catalog","url":"https://ui.shadcn.com"}],"tasks":[{"id":"core-1","text":"Configure Turborepo / pnpm workspace with strict TypeScript and ESLint configs"},{"id":"core-2","text":"Implement Prisma schema with User, MemberProfile, Problem, and Project entities"},{"id":"core-3","text":"Configure Auth.js v5 with GitHub OAuth provider and role-based session middleware"},{"id":"core-4","text":"Build responsive Dashboard, Member Profile CRUD, and Search/Filter pagination"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('core-1','core-platform','Configure Turborepo / pnpm workspace with strict TypeScript and ESLint configs') on conflict do nothing;
insert into public.milestones values('core-2','core-platform','Implement Prisma schema with User, MemberProfile, Problem, and Project entities') on conflict do nothing;
insert into public.milestones values('core-3','core-platform','Configure Auth.js v5 with GitHub OAuth provider and role-based session middleware') on conflict do nothing;
insert into public.milestones values('core-4','core-platform','Build responsive Dashboard, Member Profile CRUD, and Search/Filter pagination') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('junior-path','Junior Developer Foundation (Stages 1–6)','Structured progressive curriculum taking first-year students from terminal fundamentals to merging verified PRs in production.','{"id":"junior-path","title":"Junior Developer Foundation (Stages 1–6)","track":"foundation","stage":"Continuous","description":"Structured progressive curriculum taking first-year students from terminal fundamentals to merging verified PRs in production.","stack":["CLI / Bash","Git & GitHub","Node.js (Vanilla)","HTML5 & CSS3","React 19"],"guidelines":["No member touches React before mastering variables, functions, async/await, and DOM events.","Enforce 1 Mentor to 4 Juniors pairing ratio with weekly Friday PR deadlines.","Practice workflow: Issue → Branch → Commit → Push → PR → Review → Revision → Merge."],"resources":[{"name":"Harvard CS50x 2026","url":"https://cs50.harvard.edu/x/"},{"name":"MDN Learn Web Development","url":"https://developer.mozilla.org/en-US/docs/Learn"},{"name":"The Modern JavaScript Tutorial","url":"https://javascript.info"},{"name":"Pro Git Book (Ch 1–3)","url":"https://git-scm.com/book/en/v2"}],"tasks":[{"id":"jun-1","text":"Stage 1 Milestone: Build CLI Task Manager storing state in JSON via Node.js FS"},{"id":"jun-2","text":"Stage 2 Milestone: Create personal developer profile using semantic HTML, CSS Grid, and DOM Fetch"},{"id":"jun-3","text":"Stage 3 Milestone: Build frontend-only Problem Bank mock with client-side filters in React"},{"id":"jun-4","text":"Stage 6 Milestone: Open first reviewed feature branch PR adhering to conventional commits"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('jun-1','junior-path','Stage 1 Milestone: Build CLI Task Manager storing state in JSON via Node.js FS') on conflict do nothing;
insert into public.milestones values('jun-2','junior-path','Stage 2 Milestone: Create personal developer profile using semantic HTML, CSS Grid, and DOM Fetch') on conflict do nothing;
insert into public.milestones values('jun-3','junior-path','Stage 3 Milestone: Build frontend-only Problem Bank mock with client-side filters in React') on conflict do nothing;
insert into public.milestones values('jun-4','junior-path','Stage 6 Milestone: Open first reviewed feature branch PR adhering to conventional commits') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('dsa-bank','Curated DSA Problem Bank & Roadmap','Curated algorithmic problem set categorized by topic, difficulty, pattern, prerequisites, and editorial notes without infringing platform terms.','{"id":"dsa-bank","title":"Curated DSA Problem Bank & Roadmap","track":"cp","stage":"Core V1","description":"Curated algorithmic problem set categorized by topic, difficulty, pattern, prerequisites, and editorial notes without infringing platform terms.","stack":["PostgreSQL Problem Entity","Prerequisites Directed Graph","Zod Validation","Client-side Persistence"],"guidelines":["Do not scrape LeetCode or CodeChef statements; store canonical external links only.","Tag every problem with its core pattern (e.g. ''Two Pointers Inward'', ''Topological Sort'').","Include estimated completion time and prerequisite topic tree for every problem."],"resources":[{"name":"USACO Guide Curated Roadmap","url":"https://usaco.guide/"},{"name":"CSES Problem Set","url":"https://cses.fi/problemset/"},{"name":"CP-Algorithms Knowledge Base","url":"https://cp-algorithms.com/"},{"name":"LeetCode Explore Patterns","url":"https://leetcode.com/explore/"}],"tasks":[{"id":"dsa-1","text":"Seed 50 core algorithmic problems spanning 6 fundamental patterns into PostgreSQL"},{"id":"dsa-2","text":"Implement client-side instant search, pattern dropdown, and difficulty filters"},{"id":"dsa-3","text":"Build personal problem completion tracker with local storage & database sync"},{"id":"dsa-4","text":"Add mentor editorial submission and review workflow in admin portal"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('dsa-1','dsa-bank','Seed 50 core algorithmic problems spanning 6 fundamental patterns into PostgreSQL') on conflict do nothing;
insert into public.milestones values('dsa-2','dsa-bank','Implement client-side instant search, pattern dropdown, and difficulty filters') on conflict do nothing;
insert into public.milestones values('dsa-3','dsa-bank','Build personal problem completion tracker with local storage & database sync') on conflict do nothing;
insert into public.milestones values('dsa-4','dsa-bank','Add mentor editorial submission and review workflow in admin portal') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('algo-visualizer','Algorithm Visualization Engine','Interactive educational visualization tool demonstrating step-by-step sorting, searching, and graph algorithm state changes.','{"id":"algo-visualizer","title":"Algorithm Visualization Engine","track":"cp","stage":"Core V1","description":"Interactive educational visualization tool demonstrating step-by-step sorting, searching, and graph algorithm state changes.","stack":["TypeScript Generators","SVG Canvas","Tailwind CSS","Motion / CSS Transitions"],"guidelines":["Strict separation: decoupling algorithm computation (generators) from rendering.","Never use Three.js for 2D sorting, tree, or graph visualizations.","Provide Play, Pause, Step Forward, Step Backward, Reset, and Speed Slider controls."],"resources":[{"name":"MDN SVG Tutorial","url":"https://developer.mozilla.org/en-US/docs/Web/SVG/Tutorial"},{"name":"VisuAlgo Visual Reference","url":"https://visualgo.net/en"},{"name":"React Flow Graph Visualization","url":"https://reactflow.dev"}],"tasks":[{"id":"vis-1","text":"Implement generator-based Bubble Sort yielding comparison and swap telemetry"},{"id":"vis-2","text":"Implement generator-based Binary Search showing left/mid/right pointer transitions"},{"id":"vis-3","text":"Build responsive SVG bar stage with distinct idle, comparing, swapping, and sorted states"},{"id":"vis-4","text":"Add BFS / DFS tree traversal visualization with animated edge highlighting"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('vis-1','algo-visualizer','Implement generator-based Bubble Sort yielding comparison and swap telemetry') on conflict do nothing;
insert into public.milestones values('vis-2','algo-visualizer','Implement generator-based Binary Search showing left/mid/right pointer transitions') on conflict do nothing;
insert into public.milestones values('vis-3','algo-visualizer','Build responsive SVG bar stage with distinct idle, comparing, swapping, and sorted states') on conflict do nothing;
insert into public.milestones values('vis-4','algo-visualizer','Add BFS / DFS tree traversal visualization with animated edge highlighting') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('build-scratch','Build-from-Scratch Systems Initiative','Deep dive projects where members implement internal protocol mechanisms without relying on high-level frameworks.','{"id":"build-scratch","title":"Build-from-Scratch Systems Initiative","track":"systems","stage":"Continuous Matrix","description":"Deep dive projects where members implement internal protocol mechanisms without relying on high-level frameworks.","stack":["Node.js TCP Sockets","C++ / Rust (Optional)","Binary Filesystem","RESP Protocol"],"guidelines":["Do not recreate operating systems or raw cryptography from scratch in production.","Focus on implementing the central mechanism: Sockets, Event Loops, B-Trees, or Lexers.","Advanced projects must have a senior reviewer, written RFC design doc, and unit tests."],"resources":[{"name":"Crafting Interpreters (Robert Nystrom)","url":"https://craftinginterpreters.com"},{"name":"Write Yourself a Git","url":"https://wyag.thb.lt"},{"name":"CMU Database Systems (15-445)","url":"https://15445.courses.cs.cmu.edu"},{"name":"Redis Serialization Protocol (RESP)","url":"https://redis.io/docs/reference/protocol-spec/"}],"tasks":[{"id":"sc-1","text":"Beginner: Build Raw HTTP 1.1 Server handling TCP sockets, headers, and status codes"},{"id":"sc-2","text":"Intermediate: Implement In-Memory LRU Cache with thread-safe TTL expiration"},{"id":"sc-3","text":"Intermediate: Build Git Clone supporting blob hashing, tree objects, and commit DAG"},{"id":"sc-4","text":"Advanced: Build Bytecode Interpreter with Lexer, recursive descent parser, and stack VM"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('sc-1','build-scratch','Beginner: Build Raw HTTP 1.1 Server handling TCP sockets, headers, and status codes') on conflict do nothing;
insert into public.milestones values('sc-2','build-scratch','Intermediate: Implement In-Memory LRU Cache with thread-safe TTL expiration') on conflict do nothing;
insert into public.milestones values('sc-3','build-scratch','Intermediate: Build Git Clone supporting blob hashing, tree objects, and commit DAG') on conflict do nothing;
insert into public.milestones values('sc-4','build-scratch','Advanced: Build Bytecode Interpreter with Lexer, recursive descent parser, and stack VM') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('certs-system','Cryptographic Certificate Verification Gateway','Official credential issuance pipeline generating tamper-evident PDF certificates backed by cryptographically random UUIDs.','{"id":"certs-system","title":"Cryptographic Certificate Verification Gateway","track":"core","stage":"Release 3","description":"Official credential issuance pipeline generating tamper-evident PDF certificates backed by cryptographically random UUIDs.","stack":["PDF-Lib","Web Crypto API","Node QRCode","Supabase Storage"],"guidelines":["Never use sequential IDs like TDA-0012 (trivially guessable); use cryptographically random UUIDs.","Public verification URL must display: Recipient, Event, Issue Date, Skills, and Status (Valid/Revoked).","Embed scan-ready high-contrast QR code pointing directly to verification URL."],"resources":[{"name":"PDF-Lib Documentation","url":"https://pdf-lib.js.org/"},{"name":"W3C Web Cryptography API","url":"https://www.w3.org/TR/WebCryptoAPI/"},{"name":"OWASP Digital Certificate Security","url":"https://owasp.org"}],"tasks":[{"id":"cert-1","text":"Create PDF-Lib template with dynamic student name, event title, and issued date"},{"id":"cert-2","text":"Generate Ed25519 / UUIDv4 cryptographic hash stored in PostgreSQL Certificate table"},{"id":"cert-3","text":"Embed dynamic QR code routing to public verification gateway"},{"id":"cert-4","text":"Build public verification page with status indicator, skill badges, and PDF download"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('cert-1','certs-system','Create PDF-Lib template with dynamic student name, event title, and issued date') on conflict do nothing;
insert into public.milestones values('cert-2','certs-system','Generate Ed25519 / UUIDv4 cryptographic hash stored in PostgreSQL Certificate table') on conflict do nothing;
insert into public.milestones values('cert-3','certs-system','Embed dynamic QR code routing to public verification gateway') on conflict do nothing;
insert into public.milestones values('cert-4','certs-system','Build public verification page with status indicator, skill badges, and PDF download') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('cp-leaderboard','Codeforces Sync & CP Leaderboard','Official Codeforces REST API integration tracking member ratings, contest history, and problems solved.','{"id":"cp-leaderboard","title":"Codeforces Sync & CP Leaderboard","track":"cp","stage":"Release 2","description":"Official Codeforces REST API integration tracking member ratings, contest history, and problems solved.","stack":["Codeforces Official REST API","Redis Cache","Scheduled Cron (Vercel / Upstash)"],"guidelines":["Cache API results in Redis; never query Codeforces on every individual page render.","Adhere strictly to official Codeforces color tiers (Candidate Master purple, Expert blue, etc.).","Do not treat problems solved on different platforms as directly equivalent."],"resources":[{"name":"Codeforces Official API Documentation","url":"https://codeforces.com/apiHelp"},{"name":"Upstash Redis Caching Guide","url":"https://upstash.com/docs/redis/overall"}],"tasks":[{"id":"cf-1","text":"Implement Codeforces API client fetching user.info and user.status with error retries"},{"id":"cf-2","text":"Setup scheduled daily cron job to sync member ratings at 04:00 UTC"},{"id":"cf-3","text":"Implement Redis key-value caching layer with 6-hour TTL to prevent rate limits"},{"id":"cf-4","text":"Build responsive CP leaderboard with color-coded rank badges and max rating"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('cf-1','cp-leaderboard','Implement Codeforces API client fetching user.info and user.status with error retries') on conflict do nothing;
insert into public.milestones values('cf-2','cp-leaderboard','Setup scheduled daily cron job to sync member ratings at 04:00 UTC') on conflict do nothing;
insert into public.milestones values('cf-3','cp-leaderboard','Implement Redis key-value caching layer with 6-hour TTL to prevent rate limits') on conflict do nothing;
insert into public.milestones values('cf-4','cp-leaderboard','Build responsive CP leaderboard with color-coded rank badges and max rating') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('analytics-engine','Coding Analytics & Activity Telemetry','Aggregated metrics dashboard displaying individual streaks, problem distributions, and team velocity.','{"id":"analytics-engine","title":"Coding Analytics & Activity Telemetry","track":"core","stage":"Release 2","description":"Aggregated metrics dashboard displaying individual streaks, problem distributions, and team velocity.","stack":["Recharts","PostgreSQL Aggregations","Prisma GroupBy"],"guidelines":["Do not calculate historical statistics on every page render; pre-aggregate via daily snapshots.","Clearly label automated API data versus manually verified metrics.","Track DailyMemberMetric, ContestResult, and ProblemCompletion."],"resources":[{"name":"Recharts React Visualization Library","url":"https://recharts.org/"},{"name":"PostgreSQL Materialized Views Guide","url":"https://www.postgresql.org/docs/current/rules-materializedviews.html"}],"tasks":[{"id":"ana-1","text":"Build DailyMemberMetric aggregate database schema and migration"},{"id":"ana-2","text":"Implement Recharts difficulty distribution stacked bar (Easy / Medium / Hard)"},{"id":"ana-3","text":"Create GitHub commit and PR activity streak heatmap calendar"},{"id":"ana-4","text":"Build team velocity comparison chart for internal hackathons"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('ana-1','analytics-engine','Build DailyMemberMetric aggregate database schema and migration') on conflict do nothing;
insert into public.milestones values('ana-2','analytics-engine','Implement Recharts difficulty distribution stacked bar (Easy / Medium / Hard)') on conflict do nothing;
insert into public.milestones values('ana-3','analytics-engine','Create GitHub commit and PR activity streak heatmap calendar') on conflict do nothing;
insert into public.milestones values('ana-4','analytics-engine','Build team velocity comparison chart for internal hackathons') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('engineering-labs','TDA Engineering Lab Sandboxes','Isolated research prototypes exploring WebSockets, Docker containerization, Redis, and Vector AI.','{"id":"engineering-labs","title":"TDA Engineering Lab Sandboxes","track":"labs","stage":"Experimental","description":"Isolated research prototypes exploring WebSockets, Docker containerization, Redis, and Vector AI.","stack":["Docker Multi-stage","WebSockets / ws","pgvector","Redis"],"guidelines":["Each lab must follow: Problem → Research → Implementation → Testing → Documentation.","Labs must remain in /labs or separate branches; never pollute production Next.js core.","Complete Docker and Redis caching before exploring microservices or RAG."],"resources":[{"name":"Docker Get Started Guide","url":"https://docs.docker.com/get-started/"},{"name":"pgvector PostgreSQL Extension Docs","url":"https://github.com/pgvector/pgvector"},{"name":"MDN WebSocket API Guide","url":"https://developer.mozilla.org/en-US/docs/Web/API/WebSocket"}],"tasks":[{"id":"lab-1","text":"Lab 01: Build live WebSocket announcement push dashboard prototype"},{"id":"lab-2","text":"Lab 02: Write multi-stage Dockerfile containerizing Next.js for zero-dependency runs"},{"id":"lab-3","text":"Lab 03: Implement pgvector semantic search over curated markdown technical notes"},{"id":"lab-4","text":"Lab 04: Prototype peer-to-peer 1-on-1 code screen-share using STUN/WebRTC"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('lab-1','engineering-labs','Lab 01: Build live WebSocket announcement push dashboard prototype') on conflict do nothing;
insert into public.milestones values('lab-2','engineering-labs','Lab 02: Write multi-stage Dockerfile containerizing Next.js for zero-dependency runs') on conflict do nothing;
insert into public.milestones values('lab-3','engineering-labs','Lab 03: Implement pgvector semantic search over curated markdown technical notes') on conflict do nothing;
insert into public.milestones values('lab-4','engineering-labs','Lab 04: Prototype peer-to-peer 1-on-1 code screen-share using STUN/WebRTC') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('dev-culture','Engineering Culture, Git & PR Standards','Professional software development workflows ensuring quality code review, automated CI, and clean history.','{"id":"dev-culture","title":"Engineering Culture, Git & PR Standards","track":"ops","stage":"Continuous","description":"Professional software development workflows ensuring quality code review, automated CI, and clean history.","stack":["GitHub Actions","Conventional Commits","Vitest","Playwright"],"guidelines":["Strict branch naming: feature/*, fix/*, docs/*, test/*.","Every pull request requires: Linked issue, description, UI screenshots, and zero secrets.","Code reviews examine correctness, security, tests, and accessibility—not formatting alone."],"resources":[{"name":"Conventional Commits 1.0.0","url":"https://www.conventionalcommits.org"},{"name":"GitHub Pull Request Review Guide","url":"https://docs.github.com/en/pull-requests"},{"name":"Vitest Fast Unit Test Runner","url":"https://vitest.dev/"}],"tasks":[{"id":"ops-1","text":"Create .github/PULL_REQUEST_TEMPLATE.md and ISSUE_TEMPLATE directory"},{"id":"ops-2","text":"Configure GitHub Actions CI running lint, typecheck, and Vitest suite on every PR"},{"id":"ops-3","text":"Implement branch protection rules on main requiring 1 senior approval"},{"id":"ops-4","text":"Draft and publish TDA Engineering Maintainer Handbook for succession handover"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('ops-1','dev-culture','Create .github/PULL_REQUEST_TEMPLATE.md and ISSUE_TEMPLATE directory') on conflict do nothing;
insert into public.milestones values('ops-2','dev-culture','Configure GitHub Actions CI running lint, typecheck, and Vitest suite on every PR') on conflict do nothing;
insert into public.milestones values('ops-3','dev-culture','Implement branch protection rules on main requiring 1 senior approval') on conflict do nothing;
insert into public.milestones values('ops-4','dev-culture','Draft and publish TDA Engineering Maintainer Handbook for succession handover') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('knowledge-base','Technical Knowledge Base & Notes Repo','Permanent technical documentation repository maintained in Markdown / MDX covering DSA, web, and system design.','{"id":"knowledge-base","title":"Technical Knowledge Base & Notes Repo","track":"ops","stage":"Release 2","description":"Permanent technical documentation repository maintained in Markdown / MDX covering DSA, web, and system design.","stack":["Nextra / Docusaurus","Markdown / MDX","GitHub Organization"],"guidelines":["Do not build an overly complex custom CMS; keep markdown files version-controlled in Git.","Every document must include: Prerequisites, Objectives, Code Example, Practice Task, and Reviewer.","Categories: DSA, Frontend, Backend, Databases, Git, AI, and Career Roadmaps."],"resources":[{"name":"Nextra Static Site Framework","url":"https://nextra.site/"},{"name":"Markdown Guide Official Spec","url":"https://www.markdownguide.org/"}],"tasks":[{"id":"kb-1","text":"Establish directory structure: knowledge-base/{dsa,frontend,backend,git,ai}"},{"id":"kb-2","text":"Author 10 core pattern guides with code snippets and visual diagrams"},{"id":"kb-3","text":"Add peer review stamp and last reviewed metadata to all documents"},{"id":"kb-4","text":"Integrate full-text client search across all documentation topics"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('kb-1','knowledge-base','Establish directory structure: knowledge-base/{dsa,frontend,backend,git,ai}') on conflict do nothing;
insert into public.milestones values('kb-2','knowledge-base','Author 10 core pattern guides with code snippets and visual diagrams') on conflict do nothing;
insert into public.milestones values('kb-3','knowledge-base','Add peer review stamp and last reviewed metadata to all documents') on conflict do nothing;
insert into public.milestones values('kb-4','knowledge-base','Integrate full-text client search across all documentation topics') on conflict do nothing;
insert into public.initiatives(id,title,description,specification) values('mentorship-sprints','Peer Mentorship Cadence & Succession','Weekly knowledge transfer loop connecting 2nd-year mentors with 1st-year juniors to guarantee continuous leadership.','{"id":"mentorship-sprints","title":"Peer Mentorship Cadence & Succession","track":"ops","stage":"12-Month Cadence","description":"Weekly knowledge transfer loop connecting 2nd-year mentors with 1st-year juniors to guarantee continuous leadership.","stack":["Agile Sprint Planning","Weekly Cadence","Pair Programming"],"guidelines":["Ratio: 1 Mentor for 3–5 Juniors; never leave a first-year without an assigned mentor.","Weekly Rhythm: Mon (Issue Selection), Tue-Thu (Development), Fri (PR Open), Sat (Review), Sun (Demo).","Rotate responsibilities so all members touch frontend, backend, database, and documentation."],"resources":[{"name":"Tenure Plan Sprint Specifications","url":"#tab-roadmap"},{"name":"Effective Peer Code Review Protocols","url":"https://smartbear.com/learn/code-review/best-practices-for-peer-code-review/"}],"tasks":[{"id":"men-1","text":"Assign junior-mentor squads with dedicated GitHub project boards"},{"id":"men-2","text":"Run weekly Monday issue planning standups with scoped beginner tasks"},{"id":"men-3","text":"Enforce Friday pull request open deadlines with live screen-sharing demos"},{"id":"men-4","text":"Conduct Month 11-12 maintainer handover and successor onboarding elections"}]}'::jsonb) on conflict do nothing;
insert into public.milestones values('men-1','mentorship-sprints','Assign junior-mentor squads with dedicated GitHub project boards') on conflict do nothing;
insert into public.milestones values('men-2','mentorship-sprints','Run weekly Monday issue planning standups with scoped beginner tasks') on conflict do nothing;
insert into public.milestones values('men-3','mentorship-sprints','Enforce Friday pull request open deadlines with live screen-sharing demos') on conflict do nothing;
insert into public.milestones values('men-4','mentorship-sprints','Conduct Month 11-12 maintainer handover and successor onboarding elections') on conflict do nothing;
insert into public.tasks(id,title,description,initiative_id,track,difficulty,skills,prerequisites,instructions,criteria,deliverable,effort,resources,repository_url) select id,title,description,initiative_id,track,difficulty,skills,prerequisites,instructions,criteria,deliverable,effort,resources,repository_url from jsonb_populate_record(null::public.tasks,'{"id":"first-contribution","title":"Make your first pull request","description":"Improve one confusing sentence in the project documentation.","initiative_id":"junior-path","track":"Developer Foundations","difficulty":"Beginner","skills":["Git"],"prerequisites":"No prior contribution required. Learn the listed skills as you go.","instructions":["Read the linked resources and inspect the existing project.","Agree on a small scope with your reviewer before implementation.","Build the deliverable, test the edge cases and document how to reproduce it.","Submit a repository or pull request link with a short explanation."],"criteria":["The deliverable meets the task description.","Setup and verification steps are reproducible.","The work handles errors and contains no secrets.","An assigned reviewer has reviewed the evidence."],"deliverable":"A pull request explaining the original confusion and your improvement.","effort":2,"status":"Available","version":0,"archived":false,"resources":[{"name":"Harvard CS50x 2026","url":"https://cs50.harvard.edu/x/"},{"name":"MDN Learn Web Development","url":"https://developer.mozilla.org/en-US/docs/Learn"},{"name":"The Modern JavaScript Tutorial","url":"https://javascript.info"},{"name":"Pro Git Book (Ch 1–3)","url":"https://git-scm.com/book/en/v2"}],"repository_url":"https://github.com/ASingh2425/TDA_CnD_Planner"}'::jsonb) on conflict do nothing;
